import sys
from collections import defaultdict


def minutes(text):
    h, m = text.split(":")
    return int(h) * 60 + int(m)


def main():
    totals = defaultdict(int)

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        name, start_t, end_t = line.split()

        start = minutes(start_t)
        end = minutes(end_t)

        if end < start:
            end += 1440  # add 24 hours in minutes to wrap over midnight

        worked = end - start
        if worked == 0:
            continue

        if worked > 6 * 60:
            if worked > 9 * 60:
                worked -= 45
            else:
                worked -= 30

        totals[name] += worked

    # Sort names lexicographically (uppercase before lowercase)
    for name in sorted(totals.keys()):
        total_minutes = totals[name]
        hours = total_minutes // 60
        minutes = total_minutes % 60
        print(f"{name} {hours:02d}:{minutes:02d}")


if __name__ == "__main__":
    main()
